// Relevant ClockEntriesController shape
private readonly AsyncClockEntryService _service;
private readonly ILogger<ClockEntriesController> _logger;

public ClockEntriesController(AsyncClockEntryService service, ILogger<ClockEntriesController> logger)
{
    _service = service;
    _logger = logger;
}

[HttpPost("clock-in")]
public async Task<ActionResult<ClockEntryResponse>> ClockInAsync(ClockInRequest request, CancellationToken cancellationToken)
{
    if (request.EmployeeId <= 0)
    {
        return Problem(statusCode: StatusCodes.Status400BadRequest, title: "Invalid clock-in request", detail: "EmployeeId must be positive.");
    }

    try
    {
        _logger.LogInformation("Clock-in requested for employee {EmployeeId}", request.EmployeeId);
        bool accepted = await _service.TryClockInAsync(request.EmployeeId, request.ClockInTime, cancellationToken);
        if (!accepted)
        {
            _logger.LogWarning("Clock-in conflict for employee {EmployeeId}", request.EmployeeId);
            return Problem(statusCode: StatusCodes.Status409Conflict, title: "Clock-in conflict", detail: "The employee already has an open clock entry.");
        }

        ClockEntryResponse response = new ClockEntryResponse(request.EmployeeId, request.ClockInTime);
        string location = $"/clock-entries/{request.EmployeeId}/open";
        _logger.LogInformation("Clock-in created for employee {EmployeeId}", request.EmployeeId);
        return Created(location, response);
    }
    catch (Exception exception)
    {
        _logger.LogError(exception, "Unexpected clock-in failure for employee {EmployeeId}", request.EmployeeId);
        return Problem(statusCode: StatusCodes.Status500InternalServerError, title: "Clock-in failed", detail: "The clock-in request could not be completed.");
    }
}
